"use strict";
// A padding helper in the shape of small CommonJS packages that wrap
// Buffer.alloc: each function hands its own untyped parameters on, so the
// kind of the fill and of the encoding is known only when the call runs.
function three(size, fill, encoding) {
  return Buffer.alloc(size, fill, encoding);
}
function two(size, fill) {
  return Buffer.alloc(size, fill);
}
function literalEncoding(size, fill) {
  return Buffer.alloc(size, fill, "utf8");
}
function literalFill(size, encoding) {
  return Buffer.alloc(size, "ab", encoding);
}
function numberFill(size, encoding) {
  return Buffer.alloc(size, 7, encoding);
}
function one(size) {
  return Buffer.alloc(size);
}
function typedFill(size) {
  return Buffer.alloc(size, 1);
}
var fills = [
  ["undefined", undefined],
  ["0", 0],
  ["7", 7],
  ["257", 257],
  ["-1", -1],
  ["1.9", 1.9],
  ["NaN", NaN],
  ["Infinity", Infinity],
  ["'a'", "a"],
  ["'ab'", "ab"],
  ["''", ""],
  ["'6162'", "6162"],
  ["'é'", "é"],
  ["true", true],
  ["false", false],
  ["null", null],
  ["buffer", Buffer.from("xy")],
  ["u8", new Uint8Array([1, 2])],
  ["u16", new Uint16Array([258, 772])],
  ["emptyBuffer", Buffer.alloc(0)],
  ["{}", {}],
  ["[5]", [5]],
  [
    "valueOf",
    {
      valueOf: function () {
        return 66;
      },
    },
  ],
  ["symbol", Symbol("s")],
  ["bigint", BigInt(3)],
];
var encodings = [
  ["undefined", undefined],
  ["utf8", "utf8"],
  ["hex", "hex"],
  ["base64", "base64"],
  ["latin1", "latin1"],
  ["UTF-8", "UTF-8"],
  ["nope", "nope"],
  ["''", ""],
  ["5", 5],
  ["null", null],
];
function show(thunk) {
  try {
    return thunk().toString("hex");
  } catch (e) {
    return e.name + (e.code ? " " + e.code : "") + ": " + String(e.message).split("\n")[0];
  }
}
exports.report = function () {
  var lines = [];
  fills.forEach(function (fill) {
    encodings.forEach(function (encoding) {
      lines.push(
        "three fill=" +
          fill[0] +
          " enc=" +
          encoding[0] +
          " -> " +
          show(function () {
            return three(5, fill[1], encoding[1]);
          }),
      );
    });
    lines.push(
      "two fill=" +
        fill[0] +
        " -> " +
        show(function () {
          return two(5, fill[1]);
        }),
    );
    lines.push(
      "literalEncoding fill=" +
        fill[0] +
        " -> " +
        show(function () {
          return literalEncoding(5, fill[1]);
        }),
    );
    // Node runs no fill at all for a size of zero: no encoding is read.
    lines.push(
      "zero fill=" +
        fill[0] +
        " -> " +
        show(function () {
          return three(0, fill[1], "nope");
        }),
    );
  });
  encodings.forEach(function (encoding) {
    lines.push(
      "literalFill enc=" +
        encoding[0] +
        " -> " +
        show(function () {
          return literalFill(5, encoding[1]);
        }),
    );
    lines.push(
      "numberFill enc=" +
        encoding[0] +
        " -> " +
        show(function () {
          return numberFill(5, encoding[1]);
        }),
    );
  });
  [3, 0, -1, 1.5, "3", undefined, NaN, null, true, Infinity, 9007199254740992].forEach(function (size) {
    lines.push(
      "size=" +
        String(size) +
        " " +
        typeof size +
        " -> " +
        show(function () {
          return three(size, 1, undefined);
        }),
    );
  });
  [3, 0, -1, 1.5, NaN, Infinity].forEach(function (size) {
    lines.push(
      "number size=" +
        String(size) +
        " -> " +
        show(function () {
          return one(size);
        }) +
        " | " +
        show(function () {
          return typedFill(size);
        }),
    );
  });
  return lines;
};
